#!/bin/bash
#================================================================================================
#	This script is for creating simple LLM friendly language files in *.txt format
#	Uses language *.ts files generated by cmake.
#	Edit the variables given at the top to your liking.
#================================================================================================
InputDir=../languages
OutputDir=~/Desktop/languagesOUT
Prompt='Translate every translation line into %s using the source line above it. \nPreserve the format and XML escapes.\n\n'
#================================================================================================

# Locale-to-language names. Unknown locales fall back to their locale code.
language_name() {
    case "$1" in
        af*) echo "Afrikaans" ;;
        ar*) echo "Arabic" ;;
        bg*) echo "Bulgarian" ;;
        bn*) echo "Bengali" ;;
        ca*) echo "Catalan" ;;
        cs*) echo "Czech" ;;
        da*) echo "Danish" ;;
        de*) echo "German" ;;
        el*) echo "Greek" ;;
        en*) echo "English" ;;
        es*) echo "Spanish" ;;
        et*) echo "Estonian" ;;
        fa*) echo "Persian" ;;
        fi*) echo "Finnish" ;;
        fr*) echo "French" ;;
        he*|iw*) echo "Hebrew" ;;
        hi*) echo "Hindi" ;;
        hr*) echo "Croatian" ;;
        hu*) echo "Hungarian" ;;
        id*) echo "Indonesian" ;;
        it*) echo "Italian" ;;
        ja*) echo "Japanese" ;;
        ko*) echo "Korean" ;;
        lt*) echo "Lithuanian" ;;
        lv*) echo "Latvian" ;;
        ms*) echo "Malay" ;;
        nb*|no*) echo "Norwegian" ;;
        nl*) echo "Dutch" ;;
        pl*) echo "Polish" ;;
        pt*) echo "Portuguese" ;;
        ro*) echo "Romanian" ;;
        ru*) echo "Russian" ;;
        sk*) echo "Slovak" ;;
        sl*) echo "Slovenian" ;;
        sr*) echo "Serbian" ;;
        sv*) echo "Swedish" ;;
        th*) echo "Thai" ;;
        tr*) echo "Turkish" ;;
        uk*) echo "Ukrainian" ;;
        ur*) echo "Urdu" ;;
        vi*) echo "Vietnamese" ;;
        zh*) echo "Chinese" ;;
        *)   echo "$1" ;;
    esac
}

if [[ ! -d "$InputDir" ]]; then
    printf 'Error: input directory not found: %s\n' "$InputDir" >&2
    exit 1
fi

mkdir -p "$OutputDir" || exit 1
shopt -s nullglob
files=("$InputDir"/*.ts)

if (( ${#files[@]} == 0 )); then
    printf 'No .ts files found in: %s\n' "$InputDir"
    exit 0
fi

for ts_file in "${files[@]}"; do
    filename="${ts_file##*/}"
    basename="${filename%.ts}"
    txt_file="$OutputDir/$basename.txt"

    # Read the locale from the TS root element, e.g. language="tr_TR".
    locale=$(sed -n 's/.*language="\([^"]*\)".*/\1/p' "$ts_file" | head -n 1)
    [[ -n "$locale" ]] || locale="${basename##*_}"
    language=$(language_name "$locale")

    {
        printf "$Prompt" "$language"

        # Qt TS files normally put each source/translation element on its own line.
        # Keep the XML-escaped text intact and emit the compact delimiter format.
        awk '
            /<source([[:space:]>])/ {
                line = $0
                sub(/^.*<source[^>]*>/, "", line)
                sub(/<\/source>.*/, "", line)
                if (line != "") print "<source>" line "<"
                else print "<source><"
            }
            /<translation([[:space:]>])/ {
                line = $0
                sub(/^.*<translation[^>]*>/, "", line)
                sub(/<\/translation>.*/, "", line)
                if (line != "") print "<translation>" line "<"
                else print "<translation><"
				print ""
            }
        ' "$ts_file"
    } > "$txt_file"

    printf 'Created: %s\n' "$txt_file"
done